129	            Location where = it.next();
130	            Object animal = field.getObjectAt(where);
131	            if(animal != null && traits.getDiet().contains(animal.getClass()))
132	            {
133	                Organism food = (Organism) animal;
134	                if (food.isDiseased() &&  food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE && food.getDisease().getPropagationRate() <= rand.nextDouble()) 
135	                {
136	                    // contracts disease from food if it has a disease and that disease is foodborne
137	                    setDisease(food.getDisease());
138	                }
139	                if(food.isAlive()) 
140	                {
141	                    food.setDead();
142	                    int newFoodLevel = foodLevel + food.getFoodValue();
143	
144	                    // caps the food level at the maximum
145	                    foodLevel = Math.min(newFoodLevel, traits.getMaxFoodLevel());
146	
147	                    return where;
148	                }
149	                return where;
150	            }
151	        }
152	        return null;
153	    }
