175	    /**
176	     * Check whether this animal is to give birth at this step.
177	     * New births will be made into free adjacent locations.
178	     * @param newAnimals A list to return newly born animals.
179	     * @param environment The environment that the animal resides in. 
180	     */
181	    protected void giveBirth(List<Actor> newAnimals, Environment environment)
182	    {
183	        Field field = getField();
184	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
185	        int births = breed();
186	        for(int b = 0; b < births && free.size() > 0; b++) {
187	            Location loc = free.remove(0);
188	            Gender sex = Randomizer.getRandomSex();
189	            newAnimals.add(createOffspring(field, loc, sex));
190	        }
191	    }
