217	    /**
218	     * Generates a number representing the number of births,
219	     * if it can breed.
220	     * @return The number of births (may be zero)
221	     */
222	    protected int breed()
223	    {
224	        int births = 0;
225	        if(canBreed() && rand.nextDouble() <= traits.getBreedingProbability()) {
226	            births = rand.nextInt(traits.getMaxLitterSize()) + 1;
227	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
228	            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
229	                this.setDisease(mate.getDisease());
230	            }
231	        }
232	        return births;
233	    }
