235	    /**
236	     * Returns true if the animal is able to breed.
237	     * Returns false if otherwise. 
238	     */
239	    protected boolean canBreed()
240	    {
241	        return (age >= traits.getBreedingAge() && getPotentialMates().size() > 0);
242	    }
