244	    /**
245	     * Returns a list of potential mates. Mates have to be
246	     * of a opposite gender. 
247	     * @return List<Organism> A list of potential mates.
248	     */
249	    protected List<Organism> getPotentialMates()
250	    {
251	        List<Organism> potentialMates = new ArrayList<>();
252	        if(getField() != null){
253	            potentialMates = getField().adjacentLocations(getLocation()).stream()
254	                    .map(s -> getField().getObjectAt(s))
255	                    .filter(s -> s != null)
256	                    .filter(s -> s.getClass().equals(this.getClass()))
257	                    .filter(s -> this.sex != ((Animal) s).sex)
258	                    .map(s -> (Organism) s)
259	                    .collect(Collectors.toList());
260	            // stream counts the number of Animals of the same species, as well as opposite gender
261	        }
262	        return potentialMates;
263	    }
